def steady_runs(readings, tol=5):
    runs = []
    for i in range(len(readings)):
        count = 0
        j = i
        while j > 0 and abs(readings[j] - readings[j - 1]) <= tol:
            count += 1
            j -= 1
        runs.append(count)
    return runs

def ingest(stream):
    data = stream.read()                      # 40 GB, held in memory
    errors = []
    summary = {}
    for lineno, line in enumerate(data.split("\n"), start=1):
        fields = line.split(",")
        if len(fields) != 4:
            errors.append((lineno, line))     # keeps every bad line
            continue
        station, timestamp, temp, humidity = fields
        ...
    return summary, errors
